window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[235]={"id":"235","numero":235,"titre":"Péricardite aiguë","objectifs":[{"id":"235-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une péricardite aiguë","contenu":"<div class=\"notion-course\"><p>La péricardite aiguë est une <span>inflammation aiguë des feuillets péricardiques</span> (feuillets viscéral et pariétal du péricarde).</p>\n      <ul>\n        <li>Elle peut être <strong>accompagnée d'un <span><span class=\"nc-orange_bg\">épanchement péricardique</span></span></strong> ou non — on parle alors de <span>« <span class=\"nc-blue_bg\">péricardite</span> sèche »</span> lorsqu'il n'y a pas d'épanchement.</li>\n        <li>Lorsqu'elle est associée à une <span class=\"nc-pink_bg\">élévation de la</span> <span><span class=\"nc-red nc-bold\">troponine</span></span>, on parle de <strong><span>myo-<span class=\"nc-blue_bg\">péricardite</span></span></strong> (atteinte myocardique associée).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"nc-green_bg\">Péricardite « sèche »</span> = sans épanchement ; <span>troponine</span> élevée = myo-<span class=\"nc-blue_bg\">péricardite</span>, à ne pas confondre avec un <span>syndrome coronarien aigu</span>.</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"235-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","contenu":"<div class=\"notion-course\"><p>Le <span>diagnostic positif</span> repose sur un faisceau de critères. Le <span>terrain</span> typique est un <strong>sujet <span class=\"nc-pink nc-bold\">jeune</span></strong>, avec une <span>prédominance <span class=\"nc-pink nc-bold\">masculine</span></span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span>Critères diagnostiques</span> EDN — <span>≥ 2</span>/4 critères</h4>\n      <p>Le diagnostic est retenu devant la présence d'au moins <span>2 critères sur 4</span> :</p>\n      <ul>\n        <li><span>Douleur thoracique</span> d'allure péricarditique</li>\n        <li><span><span class=\"nc-brown_bg\">Frottement péricardique</span></span> à l'auscultation</li>\n        <li><span class=\"nc-blue_bg\">Anomalies </span><span><span class=\"nc-blue_bg\">ECG</span></span><span class=\"nc-blue_bg\"> typiques</span> (<span><span class=\"nc-red\">stade</span></span><span class=\"nc-red\"> 1</span>, ou <span class=\"nc-blue_bg\">sous-décalage PQ</span>)</li>\n        <li><span>Épanchement péricardique</span> (<span>ETT</span> systématique)</li>\n      </ul>\n      <p><strong>Critères additionnels :</strong> <span><span class=\"nc-blue_bg\">syndrome inflammatoire</span></span> (<span>CRP</span>, <span>VS</span> élevées ou hyperleucocytose) ; inflammation mise en évidence par <span><span class=\"nc-blue_bg\">IRM</span></span> ou <span><span class=\"nc-blue_bg\">TDM</span></span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">La <span>douleur thoracique</span> péricarditique</h4>\n      <table>\n        <thead><tr><th>Caractère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Localisation</td><td><span class=\"nc-blue_bg\">Rétrosternale</span> ou <span class=\"nc-blue_bg\">précordiale gauche</span></td></tr>\n          <tr><td>Durée</td><td>Prolongée, permanente</td></tr>\n          <tr><td>Majorée par</td><td>Le <span><span class=\"nc-red nc-bold\">décubitus</span></span> ; l'<span><span class=\"nc-red nc-bold\">inspiration profonde</span></span> ; la <span><span class=\"nc-red nc-bold\">toux</span></span> (douleur impulsive)</td></tr>\n          <tr><td>Calmée par</td><td>La position assise penchée en avant (<span><span class=\"nc-green_bg\">antéflexion</span></span>) = attitude <span>antalgique</span> en « prière mahométane »</td></tr>\n          <tr><td>Signes négatifs</td><td><span>Résistante à la trinitrine</span> ; ne survient pas à l'effort</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Autres symptômes</h4>\n      <ul>\n        <li><span><span class=\"nc-blue_bg nc-bold\">Fièvre</span></span> <span class=\"nc-blue_bg\">modérée</span> : présente d'emblée ; moins fréquente, voire absente, chez le sujet âgé</li>\n        <li><span><span class=\"nc-green_bg\">Syndrome grippal</span></span> (<span>myalgies</span>, <span>asthénie</span>) précédant la <span class=\"nc-blue_bg\">péricardite</span> de quelques jours</li>\n        <li>Parfois <span><span class=\"nc-blue_bg\">dyspnée</span></span> (également soulagée par l'<span class=\"nc-green nc-bold\">antéflexion</span>), <span><span class=\"nc-blue_bg\">toux sèche</span></span>, <span><span class=\"nc-blue_bg\">hoquet</span></span></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Signes physiques</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">Frottement péricardique</span></span></strong> : précoce, inconstant et <span><span class=\"nc-red nc-bold\">fugace</span></span> (varie dans le temps et avec les positions) ; <span><span class=\"nc-red nc-bold\">râpeux</span></span> (crissement de cuir neuf, froissement de soie, pas dans la neige) ; <span><span class=\"nc-red nc-bold\">systolodiastolique</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Tachycardie</span></span> souvent présente</li>\n        <li>Signes d'<span><span class=\"nc-blue_bg\">épanchement pleural</span></span> associé possibles : disparition du murmure vésiculaire, matité à la percussion</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> La présence de signes d'<span><span class=\"nc-yellow_bg\">insuffisance cardiaque droite</span></span> doit faire suspecter une <span><span class=\"nc-red_bg\">tamponnade</span></span> — ce n'est jamais banal dans une <span class=\"nc-blue_bg\">péricardite</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 230 — <span>Douleur thoracique</span></em></p><h4>Points de raisonnement et précautions</h4><ul><li>Le schéma CNEC utilise les quatre critères classiques (au moins deux). Les recommandations ESC 2025 intègrent plus explicitement la présentation clinique, les signes additionnels et l’imagerie d’inflammation ; toujours préciser le référentiel employé. Un épanchement isolé n’est pas synonyme de <span class=\"nc-blue_bg\">péricardite</span> inflammatoire.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"235-3","rang":"A","rubrique":"Identification de l’urgence","titre":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","contenu":"<div class=\"notion-course\"><p>Les <span>signes de gravité</span> doivent faire suspecter une <span><span class=\"nc-red_bg\">tamponnade</span></span> ou une <span><span class=\"nc-red_bg\">myocardite</span></span> associée. Ils s'évaluent dans 4 domaines.</p>\n      <table>\n        <thead><tr><th>Domaine</th><th><span>Signes de gravité</span></th></tr></thead>\n        <tbody>\n          <tr><td>Clinique</td><td>Signes de <span>choc</span> ; <span class=\"nc-red_bg\">signes d'</span><span><span class=\"nc-red_bg\">insuffisance cardiaque droite</span></span> ; <span><span class=\"nc-red_bg\">pouls paradoxal</span></span> ; <span>fièvre</span> <span><span class=\"nc-red nc-bold\">&gt; 38 °C</span></span></td></tr>\n          <tr><td>Biologie</td><td><span class=\"nc-pink_bg\">Élévation de la</span> <span><span class=\"nc-red nc-bold\">troponine</span></span> (oriente vers une myocardite associée)</td></tr>\n          <tr><td><span>ECG</span></td><td><span><span class=\"nc-red nc-bold\">Microvoltage</span></span> et <span><span class=\"nc-red nc-bold\">alternance électrique</span></span> (<span><span class=\"nc-red_bg\">tamponnade</span></span>) ; <span class=\"nc-red_bg\">troubles du </span><span><span class=\"nc-red_bg\">rythme ventriculaire</span></span> (<span class=\"nc-red_bg\">myocardite</span>)</td></tr>\n          <tr><td><span>ETT</span></td><td>Épanchement <span><span class=\"nc-red nc-bold\">&gt; 20 mm</span></span> ; <span class=\"nc-yellow_bg\">compression des cavités droites</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span>Urgence</span>.</strong> Devant une <span><span class=\"nc-red_bg\">tamponnade</span></span> (<span class=\"nc-red nc-bold\">épanchement</span> abondant comprimant les cavités droites, retentissement hémodynamique), il faut appeler en <span>urgence</span> pour un <strong><span>drainage</span> de l'<span><span class=\"nc-orange_bg\">épanchement péricardique</span></span></strong> — le <span>pronostic vital</span> est engagé (risque d'arrêt cardio-circulatoire par adiastolie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span>choc</span></em></p><h4>Points de raisonnement et précautions</h4><ul><li>Une tamponnade peut se produire avec un épanchement peu volumineux s’il s’installe rapidement ; ne pas conditionner l’appel pour drainage au seuil de 20 mm.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a57ccade97fe45ef?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Tamponnade péricardique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"235-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","contenu":"<div class=\"notion-course\"><ul><li>ECG souvent évocateur mais parfois normal : sus-décalage ST diffus, généralement concave, et sous-décalage PR. Une image opposée en aVR, parfois V1, est possible ; « aucun miroir dans aucune dérivation » est faux.</li><li>Les quatre stades classiques (ST élevé, <span class=\"nc-green_bg\">normalisation</span>, T négatives puis <span class=\"nc-green_bg\">normalisation</span>) ne sont ni constants ni obligatoirement synchronisés au calendrier décrit dans les schémas.</li><li>Une morphologie concave ou un PR abaissé ne permet pas à elle seule d’exclure un SCA. Interpréter <span class=\"nc-blue_bg\">avec</span> <span class=\"nc-green nc-bold\">douleur</span>, territoire, évolution, troponine et échographie ; en cas de doute, traiter le diagnostic urgent.</li><li><span class=\"nc-red nc-bold\">Microvoltage</span> et <span class=\"nc-red nc-bold\">alternance électrique</span> peuvent accompagner un épanchement important, mais sont inconstants et non suffisants pour diagnostiquer une <span class=\"nc-red_bg\">tamponnade</span>.</li><li>Bilan initial : <span class=\"nc-blue_bg\">NFS</span>, CRP, <span class=\"nc-red nc-bold\">troponine</span>, créatinine et électrolytes selon contexte ; hémocultures si infection bactérienne suspectée/<span class=\"nc-blue_bg\">fièvre</span>. La <span class=\"nc-red nc-bold\">troponine</span> évoque une atteinte myocardique associée sans en établir à elle seule la cause.</li><li>Ne pas multiplier les <span class=\"nc-blue_bg\">sérologies virales</span> dans une forme typique sans signe de gravité ; bilan étiologique ciblé selon les facteurs d’alerte.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"235-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaitre l’intérêt diagnostique d’une ponction péricardique","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-pink\">ponction péricardique</span></span> a un double intérêt : <strong>évacuateur</strong> (<span>drainage</span>) et <strong>diagnostique</strong> (analyse du liquide).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Indications</h4>\n      <ul>\n        <li><span>Tamponnade</span> (<span>drainage</span> en <span>urgence</span>)</li>\n        <li>Épanchement abondant et symptomatique <strong>malgré</strong> un traitement médical bien conduit depuis <span><span class=\"nc-pink nc-bold\">1 semaine</span></span></li>\n        <li><span class=\"nc-red_bg\">Forte suspicion de péricardite </span><span><span class=\"nc-red_bg\">néoplasique</span></span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Analyses du liquide péricardique</h4>\n      <ul>\n        <li><strong>Biochimie :</strong> <span>glucose</span>, <span>protides</span>, <span>lactates</span> déshydrogénase (<span>LDH</span>)</li>\n        <li><strong>Cytologie :</strong> recherche de cellules néoplasiques</li>\n        <li><strong>Bactériologie et virologie :</strong> Gram et <span>Ziehl-Neelsen</span>, culture, <span>PCR virale</span>, <span>PCR BK</span></li>\n      </ul>\n      <p><strong>Orientation étiologique par l'aspect macroscopique du liquide (LiSA)</strong> : <span>séreux/citrin</span> → péricardite virale ou idiopathique ; <span>purulent (louche)</span> → péricardite bactérienne ; <span><span class=\"nc-red\">hémorragique</span></span> → péricardite <span><span class=\"nc-red_bg\">néoplasique</span></span>, <span><span class=\"nc-red_bg\">tuberculeuse</span></span> ou <span class=\"nc-red_bg\">hémopéricarde</span> (<span>dissection aortique</span>, rupture de paroi post-IDM, traumatisme, iatrogène) ; <span>chyleux</span> → atteinte du canal thoracique.</p>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> En cas de suspicion de <span class=\"nc-blue_bg\">péricardite</span> <span><span class=\"nc-orange_bg\">purulente</span></span>, on privilégie un <strong><span>drainage chirurgical</span></strong> (<span class=\"nc-pink_bg\">drain</span> de plus gros calibre) plutôt qu'une simple <span>ponction</span>.</div><h4>Points de raisonnement et précautions</h4><ul><li>Une suspicion de péricardite <span class=\"nc-orange_bg\">purulente</span> justifie drainage et antibiothérapie urgente. Les analyses microbiologiques sont ciblées au contexte ; une PCR virale systématique n’est pas nécessaire dans toute ponction.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a57ccade97fe45ef?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Tamponnade péricardique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"235-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’objectif de l’imagerie dans l’exploration d’une péricardite aiguë : radiographie thoracique et échocardiographie","contenu":"<div class=\"notion-course\"><p>Le bilan d'imagerie initial associe <strong><span>ECG</span> + <span>radiographie thoracique</span> + <span>échocardiographie transthoracique</span> (<span>ETT</span>)</strong>. La <span>TDM</span> et l'<span>IRM</span> sont des examens de 2ᵉ intention.</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Apport diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><span>Radiographie thoracique</span> (<span><span class=\"nc-blue_bg\">RXT</span></span>)</td><td>\n            <strong>Le plus souvent <span class=\"nc-green_bg\">normale</span></strong><br>\n            Si <span class=\"nc-red nc-bold\">épanchement</span> abondant : <span>cardiomégalie symétrique</span>, cœur triangulaire « en carafe »<br>\n            Peut orienter l'étiologie (lésions pulmonaires, <span><span class=\"nc-blue_bg\">épanchement pleural</span></span> associé)\n          </td></tr>\n          <tr><td><span>Échocardiographie</span> (<span>ETT</span>)</td><td>\n            <strong>Peut être <span class=\"nc-green_bg\">normale</span></strong> : <span class=\"nc-green_bg\">péricardite « sèche »</span> (sans <span class=\"nc-red nc-bold\">épanchement</span>)<br>\n            <span><span class=\"nc-orange_bg\">Épaississement péricardique</span></span><br>\n            <span><span class=\"nc-red nc-bold\">Épanchement</span></span> : décollement des 2 feuillets, espace clair vide d'écho — abondance : minime <span><span class=\"nc-pink nc-bold\">&lt; 10 mm</span></span>, modéré <span>10-20 mm</span>, abondant <span><span class=\"nc-red nc-bold\">&gt; 20 mm</span></span><br>\n            Arguments pour une origine <span><span class=\"nc-red_bg nc-bold\">néoplasique</span></span> : <span><span class=\"nc-red nc-bold\">masse</span></span>, <span class=\"nc-red nc-bold\">métastases</span>, caillots, <span class=\"nc-red nc-bold\">bandes de </span><span><span class=\"nc-red nc-bold\">fibrine</span></span>, <span class=\"nc-red nc-bold\">épanchement</span> cloisonné\n          </td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">TDM</span></span><span class=\"nc-brown_bg\"> thoracique</span> / <span><span class=\"nc-brown_bg\">IRM</span></span><span class=\"nc-brown_bg\"> cardiaque</span> (2ᵉ intention)</td><td>\n            Patient peu échogène<br>\n            <span class=\"nc-red_bg\">Suspicion de péricardite </span><span><span class=\"nc-red_bg\">néoplasique</span></span> ou <span class=\"nc-red nc-bold\">épanchement</span> cloisonné<br>\n            <span class=\"nc-red_bg\">Suspicion de </span><span><span class=\"nc-red_bg\">myocardite</span></span> associée (réhaussement tardif après <span class=\"nc-blue_bg\">gadolinium</span>)\n          </td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/rxt-epanchement-pericardique.jpeg\" alt=\"Radiographie thoracique de face montrant une cardiomégalie symétrique en carafe par épanchement péricardique abondant\" loading=\"lazy\">\n        <figcaption><span>Radiographie thoracique</span> — cardiomégalie symétrique « en carafe » témoignant d'un <span>épanchement péricardique</span> abondant. Source : fiche source EDN item 235.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/ett-epanchement-pericardique.jpg\" alt=\"Échocardiographie transthoracique montrant un épanchement péricardique sous forme d&#x27;espace clair vide d&#x27;écho entre les deux feuillets\" loading=\"lazy\">\n        <figcaption><span>Échocardiographie</span> transthoracique — <span>épanchement péricardique</span> : décollement des deux feuillets, visible comme un espace clair vide d'écho. Source : fiche source EDN item 235.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span><span class=\"nc-brown_bg\">ETT</span></span> est systématique : elle confirme l'<span class=\"nc-red nc-bold\">épanchement</span>, en précise l'abondance et la localisation, et recherche un retentissement hémodynamique (<span><span class=\"nc-red_bg\">tamponnade</span></span>).</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a57ccade97fe45ef?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Tamponnade péricardique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":3},{"id":"235-7","rang":"A","rubrique":"Contenu multimédia","titre":"Electrocardiogramme (ECG) d’une péricardite aiguë","contenu":"<div class=\"notion-course\"><ul><li>Lire d’abord fréquence, rythme, conduction puis ST/PR sur l’ensemble des dérivations et comparer aux ECG antérieurs.</li><li>Aspect classique : ST diffus concave et PR abaissé ; aVR et parfois V1 peuvent présenter une image opposée. Le PR abaissé est évocateur, non pathognomonique.</li><li>Un tracé normal n’exclut pas la péricardite ; inversement un ST concave n’exclut pas un infarctus. La séquence en quatre stades reste un modèle pédagogique et non un passage obligé.</li><li>Chercher <span class=\"nc-red nc-bold\">microvoltage</span>, alternance, arythmie ou trouble de conduction, puis corréler à l’échographie et à la tolérance.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/ecg-pericardite-1.jpg\" alt=\"ECG de péricardite aiguë montrant un sus-décalage du segment ST concave vers le haut diffus et un sous-décalage du segment PQ\" loading=\"lazy\">\n        <figcaption><span>ECG</span> de péricardite aiguë — sus-décalage ST concave vers le haut, diffus, sans miroir ; sous-décalage du segment PQ. Source : fiche source EDN item 235.</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/ecg-pericardite-2.png\" alt=\"Second tracé ECG de péricardite aiguë illustrant des anomalies de repolarisation diffuses non systématisées\" loading=\"lazy\">\n        <figcaption><span>ECG</span> de péricardite aiguë (2ᵉ tracé) — anomalies de repolarisation diffuses dans toutes les dérivations sauf aVR et V1. Source : fiche source EDN item 235.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/pericarditis","label":"Radiopaedia : Pericarditis"},{"href":"https://radiopaedia.org/articles/cardiac-tamponade","label":"Radiopaedia : Cardiac tamponade"}]},{"id":"235-8","rang":"A","rubrique":"Prise en charge","titre":"Savoir évaluer les risques de complications nécessitant une hospitalisation","contenu":"<div class=\"notion-course\"><p>L'<span>hospitalisation</span> <strong>n'est pas systématique</strong>. Elle est envisagée en cas de risque de <span class=\"nc-red nc-bold\">complication</span> et/ou d'<span class=\"nc-red nc-bold\">étiologie inhabituelle</span> (&lt;<span> 20 %</span> des cas), selon des facteurs prédictifs.</p>\n      <table>\n        <thead><tr><th>Facteurs prédictifs majeurs</th><th>Facteurs prédictifs mineurs</th></tr></thead>\n        <tbody>\n          <tr><td>\n            <span><span class=\"nc-blue_bg\">Fièvre</span></span> <span><span class=\"nc-red nc-bold\">&gt; 38 °C</span></span><br>\n            Symptômes depuis plusieurs <span class=\"nc-pink\">jours</span>/semaines <span class=\"nc-blue_bg\">avec</span> <span class=\"nc-red nc-bold\">début </span><span><span class=\"nc-red nc-bold\">subaigu</span></span><br>\n            <span class=\"nc-red nc-bold\">Épanchement</span> abondant (<span><span class=\"nc-red nc-bold\">&gt; 20 mm</span></span>) ou <span><span class=\"nc-red nc-bold\">tamponnade</span></span><br>\n            <span><span class=\"nc-red nc-bold\">Résistance</span></span> au <span class=\"nc-pink nc-bold\">traitement anti-</span><span><span class=\"nc-pink nc-bold\">inflammatoire</span></span> depuis <span><span class=\"nc-red nc-bold\">&gt; 7 jours</span></span>\n          </td><td>\n            Patient <span><span class=\"nc-orange_bg\">immunodéprimé</span></span><br>\n            Patient sous <span>anticoagulant</span><br>\n            Suites d'un <span><span class=\"nc-orange_bg\">traumatisme thoracique</span></span><br>\n            <span><span class=\"nc-orange_bg\">Myocardite</span></span> associée (élévation des <span>troponines</span>)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La présence d'un seul facteur majeur, ou d'un faisceau de facteurs mineurs, justifie l'<span>hospitalisation</span> et la recherche d'une étiologie non bénigne.</div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"235-9","rang":"A","rubrique":"Etiologies","titre":"Connaître l’étiologie de la forme clinique usuelle","contenu":"<div class=\"notion-course\"><p>La forme clinique usuelle est la <strong>péricardite <span>virale ou idiopathique</span></strong> — c'est l'étiologie dominante (<span>90 %</span> des cas), liée à l'infection <span>virale</span> et à la réaction immune associée. Elle est rarement prouvée.</p>\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Virus en cause</td><td><span><span class=\"nc-purple_bg\">Entérovirus</span></span> (Coxsackie A et B), <span class=\"nc-purple_bg\">échovirus</span>, <span class=\"nc-purple_bg\">adénovirus</span>, <span><span class=\"nc-purple_bg\">CMV</span></span>, <span class=\"nc-purple_bg\">EBV</span>, <span class=\"nc-purple_bg\">herpès</span>, <span class=\"nc-purple_bg\">parvovirus B19</span>, <span class=\"nc-purple_bg\">VIH</span>, VHC, <span class=\"nc-purple_bg\">influenza</span>, <span class=\"nc-purple_bg\">COVID-19</span></td></tr>\n          <tr><td><span>Terrain</span></td><td>Sujet <span><span class=\"nc-pink nc-bold\">jeune</span></span>, prédominance <span><span class=\"nc-pink nc-bold\">masculine</span></span>, sans antécédent cardiologique notable</td></tr>\n          <tr><td>Présentation</td><td><span><span class=\"nc-green_bg\">Syndrome grippal</span></span> récent ; début <span><span class=\"nc-red nc-bold\">brutal</span></span> (<span><span class=\"nc-blue_bg nc-bold\">fièvre</span></span>, douleur typique, frottement) ; modifications <span>ECG</span> typiques ; <span>ETT le plus souvent <span class=\"nc-green_bg\">normale</span></span></td></tr>\n          <tr><td><span>Évolution</span></td><td><span class=\"nc-green_bg\">Le plus souvent </span><strong><span class=\"nc-green_bg\">favorable</span></strong> ; <span class=\"nc-orange_bg\">taux de récidive important</span> (<span>30-50 %</span>) ; complications rares hors récidive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Dans une forme typique, les <span>recherches virologiques</span> (<span>sérologies</span>, <span>PCR</span>) sont <strong>inutiles</strong> : elles n'ont pas d'implication thérapeutique. Le diagnostic est clinique.</div>\n      <p><strong>Focus <span><span class=\"nc-purple_bg\">VIH</span></span> :</strong> la <span class=\"nc-blue_bg\">péricardite</span> liée au <span class=\"nc-purple_bg\">VIH</span> s'accompagne fréquemment d'un épanchement, par des mécanismes multiples — infection par le <span class=\"nc-purple_bg\">VIH</span> lui-même, <span class=\"nc-red nc-bold\">surinfection </span><span><span class=\"nc-red nc-bold\">bactérienne</span></span><span class=\"nc-red nc-bold\"> ou fongique</span> <span class=\"nc-red_bg\">chez l'immunodéprimé</span>, ou présence d'un <span><span class=\"nc-red nc-bold\">lymphome</span></span> / <span><span class=\"nc-red nc-bold\">sarcome de Kaposi</span></span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span>VIH</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"235-10","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies de la péricardite au cours d’un infarctus du myocarde","contenu":"<div class=\"notion-course\"><p>Au décours d'un <span>infarctus du myocarde</span>, deux types de péricardite sont à connaître, distincts par leur délai et leur mécanisme.</p>\n      <table>\n        <thead><tr><th>Entité</th><th>Délai</th><th>Présentation / <span>évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-orange_bg\">Péricardite précoce</span> (épisténocardique)</td><td><span><span class=\"nc-pink nc-bold\">J3-J5</span></span></td><td>\n            <span class=\"nc-green_bg\">Habituellement </span><span><span class=\"nc-green_bg\">inflammatoire</span></span>, associée à un <span>IDM</span> étendu<br>\n            Au décours d'un <span><span class=\"nc-red nc-bold\">infarctus</span></span><span class=\"nc-red nc-bold\"> transmural</span> : possible <span><span class=\"nc-red_bg\">hémopéricarde</span></span><br>\n            <span>Évolution</span> souvent <span class=\"nc-green_bg\">favorable</span> si minime ; <span>chirurgie</span> en <span>urgence</span> en cas de <span>rupture</span> myocardique\n          </td></tr>\n          <tr><td><span><span class=\"nc-red_bg\">Syndrome de Dressler</span></span></td><td><span>2ᵉ-16ᵉ semaine</span> (classiquement la 3ᵉ)</td><td>Le <span class=\"nc-red_bg\">syndrome de Dressler</span> est une inflammation post-lésion cardiaque ; l’<span class=\"nc-red nc-bold\">allongement du QT</span> n’est pas un critère diagnostique caractéristique.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"235-11","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies de formes cliniques moins fréquentes","contenu":"<div class=\"notion-course\"><p>En dehors de la forme <span>virale</span>/idiopathique (<span>90 %</span>), de nombreuses étiologies plus rares sont à connaître — certaines graves.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Infectieuse</td><td>\n            <strong>Purulente :</strong> rare mais grave (<span>staphylocoque</span>, <span>pneumocoque</span>, <span>streptocoque</span>, <span class=\"nc-purple_bg\">BGN</span>) ; <span>terrain</span> immunodéprimé ou <span class=\"nc-red_bg\">infection sévère</span><br>\n            <strong>Tuberculeuse :</strong> sujet âgé, greffé, <span>VIH</span>, alcoolique ; risque de <span><span class=\"nc-red nc-bold\">constriction péricardique</span></span>\n          </td></tr>\n          <tr><td><span><span class=\"nc-red_bg nc-bold\">Néoplasique</span></span></td><td>\n            Tumeurs <strong>secondaires</strong> +++ : bronche, <span class=\"nc-red_bg\">sein</span>, <span>mélanome</span>, leucémie, <span class=\"nc-red nc-bold\">lymphome</span>, <span class=\"nc-red nc-bold\">sarcome de Kaposi</span><br>\n            Tumeurs primitives rares (mésothéliome péricardique), 40× moins fréquentes que les <span class=\"nc-red nc-bold\">métastases</span>\n          </td></tr>\n          <tr><td>Maladies systémiques auto-immunes</td><td>\n            <span><span class=\"nc-orange_bg\">Lupus</span></span>, <span><span class=\"nc-orange_bg\">polyarthrite rhumatoïde</span></span>, <span class=\"nc-orange_bg\">sclérodermie</span>, <span class=\"nc-orange_bg\">périartérite noueuse</span>, <span class=\"nc-orange_bg\">dermatomyosite</span><br>\n            Reste un diagnostic d'élimination\n          </td></tr>\n          <tr><td><span>Insuffisance rénale</span></td><td>Chez le patient dialysé, distinguer <span class=\"nc-blue_bg\">péricardite</span> associée à la dialyse, insuffisance d’épuration et surcharge volémique ; tout épanchement n’est pas un simple transsudat.</td></tr>\n          <tr><td>Post-péricardotomie</td><td>\n            Origine <span>inflammatoire</span> après <span>chirurgie</span> cardiaque ou transplantation<br>\n            La chirurgie cardiaque est la <strong>1ʳᵉ cause de <span class=\"nc-red nc-bold\">constriction péricardique</span></strong>\n          </td></tr>\n          <tr><td>Autres</td><td>\n            <span><span class=\"nc-orange_bg\">Hypothyroïdie</span></span><br>\n            <span>Médicamenteuse</span> : <span><span class=\"nc-pink_bg\">hydralazine</span></span>, <span><span class=\"nc-pink_bg\">pénicilline</span></span><br>\n            <span>Radique</span> : ~<span><span class=\"nc-pink nc-bold\">1 an</span></span><span class=\"nc-pink nc-bold\"> après</span> l'<span>irradiation</span> thoracique (cancer du sein gauche, <span class=\"nc-red nc-bold\">lymphome</span>), risque d'<span>évolution</span> constrictive<br>\n            <span><span class=\"nc-orange_bg\">Dissection aortique</span></span><span class=\"nc-orange_bg\"> avec </span><span><span class=\"nc-orange_bg\">tamponnade</span></span> ; <span class=\"nc-orange_bg\">traumatisme thoracique</span> (<span class=\"nc-red_bg\">hémopéricarde</span>) ; <span class=\"nc-orange_bg\">rhumatisme articulaire aigu</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> <span class=\"nc-blue_bg\">Péricardite</span> <span><span class=\"nc-orange_bg\">purulente</span></span> et <span><span class=\"nc-red_bg\">tuberculeuse</span></span> = formes graves à fort risque de <span><span class=\"nc-red_bg\">tamponnade</span></span> et de <span>constriction</span> ; toute <span class=\"nc-blue_bg\">péricardite</span> chronique (&gt;<span> <span class=\"nc-pink\">3 mois</span></span>) doit faire suspecter une cause <span class=\"nc-red_bg\">tuberculeuse</span> ou <span><span class=\"nc-red_bg\">néoplasique</span></span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span>Tuberculose</span> Enfant / Adulte · 194 — <span>Lupus</span> - SAPL · 264 — <span>Insuffisance rénale chronique</span> · 169 — <span>VIH</span> · 243 — <span><span class=\"nc-orange_bg\">Hypothyroïdie</span></span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"235-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d’une péricardite aiguë bénigne","contenu":"<div class=\"notion-course\"><ul><li>Forme présumée idiopathique/virale à faible risque : traitement ambulatoire possible avec réévaluation à environ une semaine et consignes de recours si aggravation.</li><li><span class=\"nc-pink_bg\">Aspirine</span> ou AINS à dose anti-inflammatoire, généralement une à deux semaines puis décroissance selon symptômes et inflammation, avec protection gastrique et prise en compte des contre-indications rénales, digestives et hémorragiques. Repères usuels adultes : <span class=\"nc-pink_bg\">ibuprofène</span> 600–800 mg trois fois/j ou <span class=\"nc-pink_bg\">aspirine</span> 750–1000 mg trois fois/j, à adapter au patient.</li><li>Associer colchicine pendant trois mois si possible : repère <span class=\"nc-pink nc-bold\">0,5 mg</span>/j si poids <span class=\"nc-pink nc-bold\">&lt; 70 kg</span>, <span class=\"nc-pink nc-bold\">0,5 mg</span> deux fois/j si ≥ 70 kg ; adapter à l’âge, à la fonction rénale/hépatique et aux interactions. <span class=\"nc-blue_bg\">Diarrhée</span> ou autres signes toxiques : réévaluation immédiate.</li><li>Vérifier les interactions, notamment inhibiteurs CYP3A4/P-gp et certains macrolides ; les formes sévères d’insuffisance rénale/hépatique imposent des restrictions selon le produit.</li><li>Corticoïdes seulement dans des situations sélectionnées (contre-indication/échec ou cause spécifique) après exclusion d’une infection pertinente ; faible dose et décroissance prudente. Ils ne sont pas le traitement initial d’une forme virale simple.</li><li>Éviter l’effort intense jusqu’à rémission clinique et des marqueurs/examens pertinents ; reprise individualisée, plus encadrée en cas d’atteinte myocardique.</li><li>Une <span class=\"nc-red_bg\">tamponnade</span> ou une suspicion purulente/<span class=\"nc-red_bg nc-bold\">néoplasique</span> change la stratégie : drainage et bilan spécialisé ; la colchicine ne traite pas une compression hémodynamique.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"235-13","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Savoir énumérer les principales complications d’une péricardite aiguë","contenu":"<div class=\"notion-course\"><p>Les principales complications de la péricardite aiguë sont les suivantes.</p>\n      <table>\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red_bg\">Tamponnade</span></span></td><td>Complication la plus redoutable — <span>urgence</span> vitale (<span class=\"nc-yellow_bg\">compression des cavités droites</span>, <span class=\"nc-red nc-bold\">adiastolie aiguë</span>)</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Myocardite</span> / myopéricardite</td><td>\n            <span class=\"nc-pink_bg\">Élévation de la</span> <span><span class=\"nc-red nc-bold\">troponine</span></span> ± <span><span class=\"nc-pink_bg\">CPK</span></span> (peut mimer un <span>SCA</span>)<br>\n            <span><span class=\"nc-blue_bg\">IRM</span></span> <span class=\"nc-blue_bg\">avec</span> <span class=\"nc-blue_bg\">gadolinium</span> = examen de choix : <span>réhaussement tardif sous-épicardique</span> épargnant le sous-endocarde<br>\n            Risque d'<span><span class=\"nc-red_bg\">insuffisance cardiaque</span></span> et de <span class=\"nc-red_bg\">troubles du rythme ventriculaire</span>\n          </td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Péricardite chronique </span><span><span class=\"nc-red nc-bold\">constrictive</span></span></td><td>\n            Complique <span>&lt; 10 %</span> des péricardites ; épaississement fibreux/fibrocalcaire → <span><span class=\"nc-red nc-bold\">adiastolie chronique</span></span><br>\n            <span><span class=\"nc-yellow_bg\">Insuffisance cardiaque</span></span><span class=\"nc-yellow_bg\"> droite</span> (<span class=\"nc-red\">signe de Kussmaul</span>, <strong>absence</strong> de signe de Harzer)<br>\n            Cathétérisme : <span>dip-plateau</span> + égalisation des pressions diastoliques ; traitement = <span class=\"nc-pink_bg\">péricardectomie</span>\n          </td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Péricardite</span> récidivante</td><td>\n            <strong>Complication la plus fréquente</strong> (<span>20-30 %</span>)<br>\n            Survient souvent après une <span class=\"nc-red nc-bold\">durée de traitement insuffisante</span> ; prévention par <span><span class=\"nc-pink_bg\">colchicine</span></span>\n          </td></tr>\n          <tr><td>Péricardite chronique</td><td><span>Évolution</span> &gt;<span> 3 mois</span> ; doit faire suspecter une cause <span><span class=\"nc-red_bg\">tuberculeuse</span></span> ou <span><span class=\"nc-red_bg\">néoplasique</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Récidivante = la plus fréquente ; <span><span class=\"nc-red_bg\">tamponnade</span></span> = la plus grave ; <span>constrictive</span> = la plus tardive (séquelle fibreuse).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span><span class=\"nc-red_bg\">Insuffisance cardiaque</span></span> · 339 — <span>Syndrome coronarien</span> aiguë</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a57ccade97fe45ef?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Tamponnade péricardique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"235-14","rang":"B","rubrique":"Etiologies","titre":"Savoir évoquer les principales étiologies devant une tamponnade","contenu":"<div class=\"notion-course\"><p>En théorie, <strong>toutes</strong> les péricardites peuvent se compliquer de <span>tamponnade</span>. En pratique, certaines étiologies y exposent beaucoup plus.</p>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">Néoplasiques</span></span> <strong>+++</strong> (cause la plus fréquente de <span>tamponnade</span>)</li>\n        <li><span><span class=\"nc-red_bg\">Hémopéricarde</span></span> : <span><span>dissection</span> aortique</span>, post-traumatique, post-<span class=\"nc-pink_bg\">chirurgicale</span>, post-<span>ponction</span></li>\n        <li><span>Tuberculeuse</span></li>\n        <li><span>Purulente</span></li>\n        <li><span>Virale</span> : se complique <strong>exceptionnellement</strong> de <span><span class=\"nc-red_bg\">tamponnade</span></span> (diagnostic d'exclusion)</li>\n        <li><span>Urémique</span></li>\n        <li><span>IDM</span> (notamment après <span>thrombolyse</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant une <span><span class=\"nc-red_bg\">tamponnade</span></span>, penser d'abord <span>néoplasie</span> et <span><span class=\"nc-red_bg\">hémopéricarde</span></span> ; une origine <span>virale</span> pure est rare et reste un diagnostic d'élimination.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span>choc</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a57ccade97fe45ef?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Tamponnade péricardique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"235-15","rang":"A","rubrique":"Identification de l’urgence","titre":"Savoir faire le diagnostic d’une tamponnade","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Tamponnade</span> = compression hémodynamique par le péricarde, limitant le remplissage et le débit. Le risque dépend de la vitesse d’accumulation et des pressions, pas seulement du volume.</li><li>Clinique : <span class=\"nc-blue_bg\">dyspnée</span>, tachycardie, turgescence jugulaire, hypotension/choc, <span class=\"nc-red_bg\">pouls paradoxal</span> (baisse inspiratoire de PAS &gt; <span class=\"nc-red nc-bold\">10 mmHg</span>). La triade classique peut être incomplète et la PA initialement conservée.</li><li>ETT urgente : épanchement, collapsus de l’OD surtout systolique et du VD en diastole, variations respiratoires exagérées des flux et VCI dilatée peu variable ; interprétation selon ventilation et pressions droites.</li><li>ECG : microvoltage/alternance possibles ; radiographie parfois normale si accumulation rapide. Ne pas attendre ces signes pour agir.</li><li>Appel immédiat d’une équipe capable de drainer ; monitorage et soutien prudent de la précharge si nécessaire, sans retarder le geste. Éviter les mesures réduisant brutalement le retour veineux.</li><li>Drainage percutané échoguidé ou chirurgical selon la cause et l’anatomie. En <span class=\"nc-red_bg\">hémopéricarde</span> par dissection aortique ou rupture myocardique, priorité à la chirurgie ; une ponction n’est pas une réponse interchangeable à toutes les causes.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/tamponnade-rxt-ecg.png\" alt=\"Radiographie thoracique et ECG d&#x27;une tamponnade péricardique montrant une cardiomégalie en carafe et un microvoltage avec alternance électrique\" loading=\"lazy\">\n        <figcaption><span>Tamponnade</span> péricardique — <span>radiographie thoracique</span> (cardiomégalie « en carafe ») et <span>ECG</span> (microvoltage, alternance électrique). Source : fiche source EDN item 235.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Péricardite aiguë (235)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181a7a57ccade97fe45ef?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Tamponnade péricardique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 235</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Myocardites et péricardites, 2025</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2}],"astuces":[{"type":"piege","titre":"Raisonner avant le chiffre","contenu":"<div class=\"notion-course\"><p>Interpréter un seuil avec le tableau clinique, le référentiel et les unités ; une complication aiguë impose de réévaluer immédiatement la stratégie.</p></div>"},{"type":"piege","titre":"Source et synthèse","contenu":"<div class=\"notion-course\"><p>Les schémas du collège restent accessibles. Les arbres ATLAS et leurs compléments sont explicitement identifiés et reliés aux objectifs concernés.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Rechercher les signes de gravité puis préciser la probabilité et le mécanisme.</li><li>Choisir les examens capables de modifier la décision et confronter les résultats à la clinique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Adapter la prise en charge à l’urgence, au terrain, aux contre-indications et aux préférences.</li><li>Prévoir surveillance, éducation et réévaluation ; utiliser les arbres reliés au cours.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-20-item-235-pericardite-aigue/","label":"CNEC · Item 235 ↗"},{"href":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/myocarditis-and-pericarditis/","label":"ESC · Myocardites et péricardites, 2025 ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Épanchement avec retentissement hémodynamique ?","detail":"<ul><li>Clinique et ETT urgente si doute ; PA normale ne suffit pas à rassurer.</li></ul>","branches":[{"label":"Oui / forte suspicion","to":"drainage"},{"label":"Non","to":"etiologie"}]},{"id":"drainage","kind":"urgent","label":"Appel immédiat pour drainage adapté à la cause","detail":"<ul><li>Percutané ou chirurgie ; dissection/rupture myocardique : filière chirurgicale.</li></ul>","branches":[]},{"id":"etiologie","kind":"decision","label":"Suspicion purulente, néoplasique ou autre cause ?","detail":"<ul><li>Contexte infectieux, cancer, urémie, traumatisme, post-IDM/chirurgie.</li></ul>","branches":[{"label":"Oui","to":"specialiste"},{"label":"Non et faible risque","to":"suivi"}]},{"id":"specialiste","kind":"finish","label":"Bilan ciblé et geste si indiqué","detail":"<ul><li>Analyse du liquide si ponction ; traiter la cause.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Traitement selon mécanisme et réévaluation","detail":"<ul><li>Inflammation, symptômes, CRP/ETT ; rechercher récidive ou constriction.</li></ul>","branches":[]}]},"cards":[{"i":"2f8f2f1f5af6","n":235,"o":"235-1","u":"Définition","t":"Connaître la définition d’une péricardite aiguë","q":"Quand parle-t-on de myopéricardite lors d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><p>On parle de <strong>myopéricardite</strong> lorsqu'une <span class=\"nc-blue_bg\">péricardite</span> aiguë est associée à une <strong><span class=\"nc-pink_bg\">élévation de la</span> <span class=\"nc-red nc-bold\">troponine</span></strong> (signe d'une atteinte myocardique associée). Il ne faut pas la confondre avec un syndrome coronarien aigu.</p></div>"},{"i":"615225b2660d","n":235,"o":"235-1","u":"Définition","t":"Connaître la définition d’une péricardite aiguë","q":"Comment qualifie-t-on une péricardite aiguë sans épanchement péricardique ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-blue_bg\">péricardite</span> aiguë sans <span class=\"nc-orange_bg\">épanchement péricardique</span> est appelée <strong>« <span class=\"nc-blue_bg\">péricardite</span> sèche »</strong>.</p></div>"},{"i":"e26c1c8b3ec5","n":235,"o":"235-1","u":"Définition","t":"Connaître la définition d’une péricardite aiguë","q":"Quelle est la définition d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><p>La péricardite aiguë est définie comme une <strong>inflammation aiguë des feuillets péricardiques</strong> (viscéral et pariétal).</p></div>"},{"i":"3cb99f4540e4","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quand et pour quelles raisons un drainage péricardique peut-il être indiqué dans la péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Une <span class=\"nc-red_bg\">tamponnade</span> ou une suspicion purulente/<span class=\"nc-red_bg nc-bold\">néoplasique</span> change la stratégie : drainage et bilan spécialisé ; la colchicine ne traite pas une compression hémodynamique.</li></ul></div>"},{"i":"6ade299588a7","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quelle est la stratégie médicamenteuse de première intention pour traiter une péricardite aiguë bénigne ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">Aspirine</span> ou AINS à dose anti-inflammatoire, généralement une à deux semaines puis décroissance selon symptômes et inflammation, avec protection gastrique et prise en compte des contre-indications rénales, digestives et hémorragiques. Repères usuels adultes : <span class=\"nc-pink_bg\">ibuprofène</span> 600–800 mg trois fois/j ou <span class=\"nc-pink_bg\">aspirine</span> 750–1000 mg trois fois/j, à adapter au patient.</li><li>Associer colchicine pendant trois mois si possible : repère <span class=\"nc-pink nc-bold\">0,5 mg</span>/j si poids <span class=\"nc-pink nc-bold\">&lt; 70 kg</span>, <span class=\"nc-pink nc-bold\">0,5 mg</span> deux fois/j si ≥ 70 kg ; adapter à l’âge, à la fonction rénale/hépatique et aux interactions. <span class=\"nc-blue_bg\">Diarrhée</span> ou autres signes toxiques : réévaluation immédiate.</li></ul></div>"},{"i":"b7853c506192","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quels sont les éléments importants à connaître concernant la colchicine dans le cadre d'une péricardite aiguë bénigne ?","a":"<div class=\"notion-course\"><ul><li>Associer colchicine pendant trois mois si possible : repère <span class=\"nc-pink nc-bold\">0,5 mg</span>/j si poids <span class=\"nc-pink nc-bold\">&lt; 70 kg</span>, <span class=\"nc-pink nc-bold\">0,5 mg</span> deux fois/j si ≥ 70 kg ; adapter à l’âge, à la fonction rénale/hépatique et aux interactions. <span class=\"nc-blue_bg\">Diarrhée</span> ou autres signes toxiques : réévaluation immédiate.</li><li>Vérifier les interactions, notamment inhibiteurs CYP3A4/P-gp et certains macrolides ; les formes sévères d’insuffisance rénale/hépatique imposent des restrictions selon le produit.</li></ul></div>"},{"i":"d111fa2b860d","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Dans quel contexte et selon quelles modalités peut-on envisager les corticoïdes dans le traitement de la péricardite aiguë bénigne ?","a":"<div class=\"notion-course\"><ul><li>Corticoïdes seulement dans des situations sélectionnées (contre-indication/échec ou cause spécifique) après exclusion d’une infection pertinente ; faible dose et décroissance prudente. Ils ne sont pas le traitement initial d’une forme virale simple.</li></ul></div>"},{"i":"ee97e014fce4","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quelles sont les mesures générales recommandées pour la prise en charge d'une péricardite aiguë bénigne ?","a":"<div class=\"notion-course\"><ul><li>Forme présumée idiopathique/virale à faible risque : traitement ambulatoire possible avec réévaluation à environ une semaine et consignes de recours si aggravation.</li><li>Éviter l’effort intense jusqu’à rémission clinique et des marqueurs/examens pertinents ; reprise individualisée, plus encadrée en cas d’atteinte myocardique.</li></ul></div>"},{"i":"0b3eeb457217","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Qu'est-ce que la péricardite chronique constrictive, complication de la péricardite aiguë, et comment est posé son diagnostic ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red nc-bold\">péricardite chronique constrictive</span> est une complication d'une <span class=\"nc-blue_bg\">péricardite</span> aiguë qui survient dans <strong>moins de 10%</strong> des cas. Elle est due à un <strong><span class=\"nc-brown_bg\">épaississement fibreux ou fibrocalcaire du péricarde</span></strong> entraînant une <strong><span class=\"nc-red nc-bold\">adiastolie chronique</span></strong>, et se manifeste par une <strong><span class=\"nc-yellow_bg\">insuffisance cardiaque droite</span></strong> (avec <span class=\"nc-red\">signe de Kussmaul</span> et absence de signe de Harzer). Le diagnostic est évoqué par le cathétérisme cardiaque montrant un <strong>pattern « dip-plateau »</strong> et une <strong>égalisation des pressions diastoliques</strong>. Le traitement est la <span class=\"nc-pink_bg\">péricardectomie</span>.</p></div>"},{"i":"446f4918f618","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Comment la myocardite ou myopéricardite, complication de la péricardite aiguë, est-elle caractérisée et quel est son examen de choix ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red_bg\">myocardite</span>/myopéricardite se caractérise par une <strong><span class=\"nc-pink_bg\">élévation de la</span> <span class=\"nc-red nc-bold\">troponine</span></strong> (± <span class=\"nc-pink_bg\">CPK</span>), pouvant mimer un SCA. L'examen de choix est l'<strong><span class=\"nc-blue_bg\">IRM</span> cardiaque <span class=\"nc-blue_bg\">avec</span> <span class=\"nc-blue_bg\">injection</span> de <span class=\"nc-blue_bg\">gadolinium</span></strong>, montrant un rehaussement tardif sous-épicardique épargnant le sous-endocarde. Ses risques sont l'<span class=\"nc-red_bg\">insuffisance cardiaque</span> et les <span class=\"nc-red_bg\">troubles du rythme ventriculaire</span>.</p></div>"},{"i":"48dfde0e3284","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Quand suspecter une péricardite chronique et à quelles étiologies spécifiques doit-elle faire penser ?","a":"<div class=\"notion-course\"><p>On parle de péricardite chronique lorsqu'elle évolue depuis <strong>plus de 3 mois</strong>. Elle doit faire suspecter une étiologie <strong><span class=\"nc-red_bg\">tuberculeuse</span> ou <span class=\"nc-red_bg\">néoplasique</span></strong>.</p></div>"},{"i":"70c88b0690ae","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Quelle est la complication la plus fréquente de la péricardite aiguë et comment peut-elle être prévenue ?","a":"<div class=\"notion-course\"><p>La complication la plus fréquente de la <span class=\"nc-blue_bg\">péricardite</span> aiguë est la <strong><span class=\"nc-blue_bg\">péricardite</span> récidivante</strong>, survenant dans <strong>20 à 30% des cas</strong>. Elle survient souvent après une <span class=\"nc-red nc-bold\">durée de traitement insuffisante</span>. Sa prévention repose sur la <strong><span class=\"nc-pink_bg\">colchicine</span></strong>.</p></div>"},{"i":"cb194de87c63","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Quelle est la complication la plus redoutable de la péricardite aiguë et ses caractéristiques ?","a":"<div class=\"notion-course\"><p>La complication la plus redoutable de la péricardite aiguë est la <strong><span class=\"nc-red_bg\">tamponnade</span></strong>. C'est une urgence vitale caractérisée par une compression des cavités cardiaques droites, entraînant une <strong><span class=\"nc-red nc-bold\">adiastolie aiguë</span></strong>.</p></div>"},{"i":"2a6bdb6859f2","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les éléments paracliniques permettant de confirmer le diagnostic de tamponnade ?","a":"<div class=\"notion-course\"><ul><li>ETT urgente : épanchement, collapsus de l’OD surtout systolique et du VD en diastole, variations respiratoires exagérées des flux et VCI dilatée peu variable ; interprétation selon ventilation et pressions droites.</li><li>ECG : microvoltage/alternance possibles ; radiographie parfois normale si accumulation rapide. Ne pas attendre ces signes pour agir.</li></ul></div>"},{"i":"415b0020fd50","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les signes cliniques clés d'une tamponnade cardiaque ?","a":"<div class=\"notion-course\"><ul><li>Clinique : <span class=\"nc-blue_bg\">dyspnée</span>, tachycardie, turgescence jugulaire, hypotension/choc, <span class=\"nc-red_bg\">pouls paradoxal</span> (baisse inspiratoire de PAS &gt; <span class=\"nc-red nc-bold\">10 mmHg</span>). La triade classique peut être incomplète et la PA initialement conservée.</li></ul></div>"},{"i":"54446a0e4e3d","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les principes de prise en charge d'une tamponnade cardiaque ?","a":"<div class=\"notion-course\"><ul><li>Appel immédiat d’une équipe capable de drainer ; monitorage et soutien prudent de la précharge si nécessaire, sans retarder le geste. Éviter les mesures réduisant brutalement le retour veineux.</li><li>Drainage percutané échoguidé ou chirurgical selon la cause et l’anatomie. En <span class=\"nc-red_bg\">hémopéricarde</span> par dissection aortique ou rupture myocardique, priorité à la chirurgie ; une ponction n’est pas une réponse interchangeable à toutes les causes.</li></ul></div>"},{"i":"678876058ad1","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quelle est la définition de la tamponnade cardiaque ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Tamponnade</span> = compression hémodynamique par le péricarde, limitant le remplissage et le débit. Le risque dépend de la vitesse d’accumulation et des pressions, pas seulement du volume.</li></ul></div>"},{"i":"ad93cc4cb4fc","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Comment interpréter la physiopathologie de la tamponnade cardiaque ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Tamponnade</span> = compression hémodynamique par le péricarde, limitant le remplissage et le débit. Le risque dépend de la vitesse d’accumulation et des pressions, pas seulement du volume.</li></ul></div>"},{"i":"f860339fa646","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les pièges à éviter dans la prise en charge d'une tamponnade cardiaque ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Tamponnade</span> = compression hémodynamique par le péricarde, limitant le remplissage et le débit. Le risque dépend de la vitesse d’accumulation et des pressions, pas seulement du volume.</li><li>Clinique : <span class=\"nc-blue_bg\">dyspnée</span>, tachycardie, turgescence jugulaire, hypotension/choc, <span class=\"nc-red_bg\">pouls paradoxal</span> (baisse inspiratoire de PAS &gt; <span class=\"nc-red nc-bold\">10 mmHg</span>). La triade classique peut être incomplète et la PA initialement conservée.</li><li>Drainage percutané échoguidé ou chirurgical selon la cause et l’anatomie. En <span class=\"nc-red_bg\">hémopéricarde</span> par dissection aortique ou rupture myocardique, priorité à la chirurgie ; une ponction n’est pas une réponse interchangeable à toutes les causes.</li></ul></div>"},{"i":"12760eced371","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quelles sont les caractéristiques de la douleur thoracique d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><p>La douleur thoracique péricarditique présente les caractéristiques suivantes :</p><ul><li><strong>Localisation</strong> : <span class=\"nc-blue_bg\">Rétrosternale</span> ou <span class=\"nc-blue_bg\">précordiale gauche</span>.</li><li><strong>Durée</strong> : Prolongée, permanente.</li><li><strong>Majorée par</strong> : Le <span class=\"nc-red nc-bold\">décubitus</span>, l'<span class=\"nc-red nc-bold\">inspiration profonde</span>, la <span class=\"nc-red nc-bold\">toux</span> (douleur impulsive).</li><li><strong>Calmée par</strong> : La position <strong>assise penchée en avant</strong> (<span class=\"nc-green_bg\">antéflexion</span>), appelée « prière mahométane ».</li><li><strong>Signes négatifs</strong> : Elle est résistante à la trinitrine et ne survient pas à l'effort.</li></ul></div>"},{"i":"159b8e0b5edc","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quels sont les autres signes et symptômes cliniques fréquemment associés à la péricardite aiguë ?","a":"<div class=\"notion-course\"><p>Outre la <span class=\"nc-green nc-bold\">douleur</span> thoracique et le <span class=\"nc-brown_bg\">frottement péricardique</span>, les signes et symptômes associés à la <span class=\"nc-blue_bg\">péricardite</span> aiguë peuvent inclure :</p><ul><li>Une <strong><span class=\"nc-blue_bg nc-bold\">fièvre</span> <span class=\"nc-blue_bg\">modérée</span></strong> (présente d'emblée, moins fréquente chez le sujet âgé).</li><li>Un <strong><span class=\"nc-green_bg\">syndrome grippal</span></strong> (myalgies, asthénie) précédant la <span class=\"nc-blue_bg\">péricardite</span> de quelques jours.</li><li>Parfois une <strong><span class=\"nc-blue_bg\">dyspnée</span></strong> (également soulagée par l'<span class=\"nc-green nc-bold\">antéflexion</span>), une <span class=\"nc-blue_bg\">toux sèche</span> ou un <span class=\"nc-blue_bg\">hoquet</span>.</li><li>Un <strong><span class=\"nc-yellow_bg\">frottement péricardique</span></strong> dont la particularité est d'être précoce, inconstant et <span class=\"nc-red nc-bold\">fugace</span>, de sonorité râpeuse (comparable à un « crissement de cuir neuf »). Il est <span class=\"nc-red nc-bold\">systolodiastolique</span>.</li><li>Une <strong><span class=\"nc-blue_bg\">tachycardie</span></strong> souvent présente.</li><li>Des signes d'<strong><span class=\"nc-blue_bg\">épanchement pleural</span> associé</strong> possibles : disparition du murmure vésiculaire, matité à la percussion.</li></ul></div>"},{"i":"7443f9c3f0fb","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quels sont les critères diagnostiques essentiels d'une péricardite aiguë selon les recommandations EDN ?","a":"<div class=\"notion-course\"><p>Le diagnostic de péricardite aiguë est retenu si au moins <strong>2 des 4 critères</strong> suivants sont présents :</p><ul><li>Une <strong>douleur thoracique</strong> d'allure péricarditique.</li><li>Un <strong><span class=\"nc-brown_bg\">frottement péricardique</span></strong> à l'auscultation.</li><li>Des <span class=\"nc-blue_bg\">anomalies </span><strong><span class=\"nc-blue_bg\">ECG typiques</span></strong> (<span class=\"nc-red\">stade 1</span> ou sous-décalage de l'intervalle PQ).</li><li>Un <strong><span class=\"nc-red nc-bold\">épanchement</span> péricardique</strong> (visibles à l'échographie transthoracique).</li></ul></div>"},{"i":"903455fe2630","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quel signe clinique doit alerter sur une complication grave en cas de péricardite aiguë ?","a":"<div class=\"notion-course\"><p>La présence de <strong>signes d'<span class=\"nc-yellow_bg\">insuffisance cardiaque droite</span></strong> doit faire suspecter une <strong><span class=\"nc-red_bg\">tamponnade</span></strong>. Ce n'est jamais un signe bénin dans le contexte d'une péricardite aiguë.</p></div>"},{"i":"2c22028859e8","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quel signe biologique est en faveur d'une myocardite associée à la péricardite aiguë ?","a":"<div class=\"notion-course\"><p>L'<strong><span class=\"nc-pink_bg\">élévation de la</span> <span class=\"nc-red nc-bold\">troponine</span></strong> est un signe biologique en faveur d'une <span class=\"nc-red_bg\">myocardite</span> associée à la péricardite aiguë.</p></div>"},{"i":"8a43938011d0","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quels sont les signes cliniques de gravité permettant de suspecter une tamponnade ou une myocardite associée dans le cadre d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><p>Les signes cliniques de gravité d'une péricardite aiguë sont :</p><ul><li>Signes de <strong>choc</strong>.</li><li><span class=\"nc-red_bg\">Signes d'</span><strong><span class=\"nc-red_bg\">insuffisance cardiaque droite</span></strong>.</li><li><strong><span class=\"nc-red_bg\">Pouls paradoxal</span></strong> (signe évocateur de <span class=\"nc-red_bg\">tamponnade</span>).</li><li><strong>Fièvre &gt; 38 °C</strong>.</li></ul></div>"},{"i":"cc81b6ad457e","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quels sont les signes échocardiographiques de gravité d'une péricardite aiguë, en particulier ceux évoquant une tamponnade ?","a":"<div class=\"notion-course\"><p>Les signes échocardiographiques (ETT) de gravité d'une péricardite aiguë sont :</p><ul><li>Un <strong>épanchement péricardique <span class=\"nc-red nc-bold\">&gt; 20 mm</span></strong>.</li><li>Une <strong><span class=\"nc-yellow_bg\">compression des cavités droites</span></strong>, ce qui est un signe direct de <span class=\"nc-red_bg\">tamponnade</span>.</li></ul></div>"},{"i":"d0fd865e5fb7","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quels sont les signes ECG de gravité d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><p>Les signes ECG de gravité d'une péricardite aiguë sont :</p><ul><li><strong>Microvoltage</strong> et <strong><span class=\"nc-red nc-bold\">alternance électrique</span></strong>, qui sont des signes de <span class=\"nc-red_bg\">tamponnade</span>.</li><li><span class=\"nc-red_bg\">Troubles du </span><strong><span class=\"nc-red_bg\">rythme ventriculaire</span></strong>, qui orientent vers une myocardite associée.</li></ul></div>"},{"i":"e01453c5dd20","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quelle est l'attitude à adopter en cas de tamponnade cardiaque par épanchement péricardique ?","a":"<div class=\"notion-course\"><p>En présence d'une <strong><span class=\"nc-red nc-bold\">tamponnade cardiaque</span></strong> (<span class=\"nc-red nc-bold\">épanchement</span> abondant comprimant les cavités droites, <span class=\"nc-blue_bg\">avec</span> retentissement hémodynamique), il faut <strong>appeler en urgence pour un drainage de l'<span class=\"nc-orange_bg\">épanchement péricardique</span></strong>. Le pronostic vital est engagé en raison du risque d'arrêt cardio-circulatoire par adiastolie.</p></div>"},{"i":"bfb7b49e7e83","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Comment évolue typiquement le sus-décalage du segment ST à l'ECG au cours des différents stades d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Les quatre stades classiques (ST élevé, <span class=\"nc-green_bg\">normalisation</span>, T négatives puis <span class=\"nc-green_bg\">normalisation</span>) ne sont ni constants ni obligatoirement synchronisés au calendrier décrit dans les schémas.</li></ul></div>"},{"i":"df71fdd02fd6","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Quels signes électrocardiographiques spécifiques doit-on rechercher en cas d'épanchement péricardique abondant lors d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red nc-bold\">Microvoltage</span> et <span class=\"nc-red nc-bold\">alternance électrique</span> peuvent accompagner un épanchement important, mais sont inconstants et non suffisants pour diagnostiquer une <span class=\"nc-red_bg\">tamponnade</span>.</li></ul></div>"},{"i":"f01954c16c25","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Quelles sont les anomalies électrocardiographiques précoces pouvant être observées lors d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>ECG souvent évocateur mais parfois normal : sus-décalage ST diffus, généralement concave, et sous-décalage PR. Une image opposée en aVR, parfois V1, est possible ; « aucun miroir dans aucune dérivation » est faux.</li><li>Une morphologie concave ou un PR abaissé ne permet pas à elle seule d’exclure un SCA. Interpréter <span class=\"nc-blue_bg\">avec</span> <span class=\"nc-green nc-bold\">douleur</span>, territoire, évolution, troponine et échographie ; en cas de doute, traiter le diagnostic urgent.</li></ul></div>"},{"i":"f056a6e058a7","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Quels sont les examens biologiques initiaux essentiels à réaliser lors de la prise en charge d'une péricardite aiguë et leur objectif ?","a":"<div class=\"notion-course\"><ul><li>Bilan initial : <span class=\"nc-blue_bg\">NFS</span>, CRP, <span class=\"nc-red nc-bold\">troponine</span>, créatinine et électrolytes selon contexte ; hémocultures si infection bactérienne suspectée/<span class=\"nc-blue_bg\">fièvre</span>. La <span class=\"nc-red nc-bold\">troponine</span> évoque une atteinte myocardique associée sans en établir à elle seule la cause.</li></ul></div>"},{"i":"5ad7e07a3e6a","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Quelles anomalies ECG sont caractéristiques et précoces d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Aspect classique : ST diffus concave et PR abaissé ; aVR et parfois V1 peuvent présenter une image opposée. Le PR abaissé est évocateur, non pathognomonique.</li></ul></div>"},{"i":"661368c049ed","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Quelle est la principale distinction ECG entre une péricardite aiguë et un syndrome coronaire aigu (SCA) ?","a":"<div class=\"notion-course\"><ul><li>Aspect classique : ST diffus concave et PR abaissé ; aVR et parfois V1 peuvent présenter une image opposée. Le PR abaissé est évocateur, non pathognomonique.</li><li>Un tracé normal n’exclut pas la péricardite ; inversement un ST concave n’exclut pas un infarctus. La séquence en quatre stades reste un modèle pédagogique et non un passage obligé.</li></ul></div>"},{"i":"b36ea586543e","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Quels signes ECG spécifiques peut-on observer en cas d'épanchement péricardique abondant lors d'une péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red nc-bold\">Microvoltage</span> et <span class=\"nc-red nc-bold\">alternance électrique</span> peuvent accompagner un épanchement important, mais sont inconstants et non suffisants pour diagnostiquer une <span class=\"nc-red_bg\">tamponnade</span>.</li></ul></div>"},{"i":"ed3d596f3181","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Comment évoluent les anomalies ECG d'une péricardite aiguë au cours des 4 stades décrits par la tétrade de Holtzman ?","a":"<div class=\"notion-course\"><ul><li>Les quatre stades classiques (ST élevé, <span class=\"nc-green_bg\">normalisation</span>, T négatives puis <span class=\"nc-green_bg\">normalisation</span>) ne sont ni constants ni obligatoirement synchronisés au calendrier décrit dans les schémas.</li></ul></div>"},{"i":"210ee771cb54","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Quels sont les facteurs prédictifs dits \"majeurs\" qui justifient l'hospitalisation d'un patient atteint de péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Une <strong>fièvre &gt; 38 °C</strong>.</li><li>Un <strong><span class=\"nc-orange_bg\">épanchement péricardique</span> abondant (<span class=\"nc-red nc-bold\">&gt; 20 mm</span>)</strong> ou une <strong><span class=\"nc-red nc-bold\">tamponnade</span></strong>.</li></ul></div>"},{"i":"220cd48df27d","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Quels sont les facteurs prédictifs dits \"mineurs\" qui doivent faire envisager l'hospitalisation d'un patient atteint de péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Des symptômes évoluant depuis <strong>plusieurs jours/semaines</strong> avec un <span class=\"nc-red nc-bold\">début subaigu</span>.</li><li>Une <strong><span class=\"nc-red nc-bold\">résistance</span> au <span class=\"nc-pink nc-bold\">traitement anti-inflammatoire</span> depuis <span class=\"nc-red nc-bold\">&gt; 7 jours</span></strong>.</li><li>Un patient <strong>immunodéprimé</strong>.</li><li>Un patient sous <strong>anticoagulant</strong>.</li><li>Les suites d'un <strong><span class=\"nc-orange_bg\">traumatisme thoracique</span></strong>.</li><li>Une <strong><span class=\"nc-orange_bg\">myocardite</span> associée</strong> (révélée par l'élévation des troponines).</li></ul></div>"},{"i":"6a263afd9c54","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Quelle est la conduite à tenir face à la présence de facteurs prédictifs de complications chez un patient atteint de péricardite aiguë ?","a":"<div class=\"notion-course\"><p>La présence d'un <strong>seul facteur majeur</strong>, ou d'un <strong>faisceau de facteurs mineurs</strong>, justifie à la fois l'hospitalisation du patient et la recherche d'une étiologie non bénigne de la péricardite aiguë.</p></div>"},{"i":"dbb58f6be4db","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Dans le contexte d'une péricardite aiguë, l'hospitalisation est-elle systématique ?","a":"<div class=\"notion-course\"><p>Non, l'hospitalisation n'est <strong>pas systématique</strong> pour une péricardite aiguë. Elle est envisagée en cas de risque de <span class=\"nc-red nc-bold\">complication</span> ou d'<span class=\"nc-red nc-bold\">étiologie inhabituelle</span>.</p></div>"},{"i":"088cae7c5892","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quelles sont les caractéristiques épidémiologiques et le contexte de survenue typiques d'une péricardite aiguë virale ou idiopathique ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-blue_bg\">péricardite</span> aiguë virale ou idiopathique survient typiquement chez le <strong>sujet <span class=\"nc-pink nc-bold\">jeune</span></strong>, avec une prédominance <span class=\"nc-pink nc-bold\">masculine</span>, sans antécédent cardiologique notable. Elle est souvent précédée d'un <strong><span class=\"nc-green_bg\">syndrome grippal</span> récent</strong>.</p></div>"},{"i":"1529e42e296a","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quelle est l'implication des recherches virologiques (sérologies, PCR) dans le diagnostic d'une péricardite aiguë typique ?","a":"<div class=\"notion-course\"><p>Dans une forme typique de péricardite aiguë, les recherches virologiques (sérologies, PCR) sont considérées comme <strong>inutiles</strong>. Elles n'ont pas d'implication thérapeutique et le diagnostic est avant tout clinique.</p></div>"},{"i":"718e33528d93","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Pour la péricardite chez le patient VIH, quelles sont les causes possibles d'épanchement péricardique ?","a":"<div class=\"notion-course\"><p>Chez le patient VIH, la <span class=\"nc-blue_bg\">péricardite</span> avec épanchement peut avoir des mécanismes multiples : l'infection par le <strong>VIH lui-même</strong>, une <strong><span class=\"nc-red nc-bold\">surinfection bactérienne ou fongique</span></strong> (<span class=\"nc-red_bg\">chez l'immunodéprimé</span>), ou la présence d'un <strong><span class=\"nc-red nc-bold\">lymphome</span> ou d'un <span class=\"nc-red nc-bold\">sarcome de Kaposi</span></strong>.</p></div>"},{"i":"c18b6acd0194","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quels sont les virus fréquemment impliqués dans la péricardite aiguë virale ?","a":"<div class=\"notion-course\"><p>Les virus fréquemment impliqués dans la péricardite aiguë virale incluent les <strong><span class=\"nc-purple_bg\">entérovirus</span></strong> (Coxsackie A et B), les <span class=\"nc-purple_bg\">échovirus</span>, les <span class=\"nc-purple_bg\">adénovirus</span>, le <span class=\"nc-purple_bg\">CMV</span>, l'<span class=\"nc-purple_bg\">EBV</span>, les <span class=\"nc-purple_bg\">herpès</span> virus, le <span class=\"nc-purple_bg\">parvovirus B19</span>, le <span class=\"nc-purple_bg\">VIH</span>, le VHC, les virus <span class=\"nc-purple_bg\">influenza</span> et le <span class=\"nc-purple_bg\">COVID-19</span>.</p></div>"},{"i":"e1a1cf7e9259","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quelle est l'étiologie dominante de la péricardite aiguë dans sa forme clinique usuelle ?","a":"<div class=\"notion-course\"><p>L'étiologie dominante de la <span class=\"nc-blue_bg\">péricardite</span> aiguë usuelle est d'origine <strong>virale ou idiopathique</strong>, représentant environ <strong>90 % des cas</strong>.</p></div>"},{"i":"a78ad8f04afe","n":235,"o":"235-5","u":"Examens complémentaires","t":"Connaitre l’intérêt diagnostique d’une ponction péricardique","q":"Connaitre l’intérêt diagnostique d’une ponction péricardique ?","a":"<div class=\"notion-course\"><ul><li>La <span><span class=\"nc-pink\"><span class=\"nc-pink\">ponction péricardique</span></span></span> a un double intérêt : <strong>évacuateur</strong> (<span>drainage</span>) et <strong>diagnostique</strong> (analyse du liquide).</li><li>Épanchement abondant et symptomatique <strong>malgré</strong> un traitement médical bien conduit depuis <span><span class=\"nc-pink nc-bold\"><span class=\"nc-pink nc-bold\">1 semaine</span></span></span></li><li><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">Forte suspicion de péricardite </span></span><span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">néoplasique</span></span></span></li><li><strong>Biochimie :</strong> <span>glucose</span>, <span>protides</span>, <span>lactates</span> déshydrogénase (<span>LDH</span>)</li></ul></div>"},{"i":"11a2c2cd9707","n":235,"o":"235-6","u":"Examens complémentaires","t":"Connaître l’objectif de l’imagerie dans l’exploration d’une péricardite aiguë : radiographie thoracique et échocardiographie","q":"Quels sont les points clés concernant l’objectif de l’imagerie dans l’exploration d’une péricardite aiguë : radiographie thoracique et échocardiographie ?","a":"<div class=\"notion-course\"><ul><li>Le bilan d'imagerie initial associe <strong><span>ECG</span> + <span>radiographie thoracique</span> + <span>échocardiographie transthoracique</span> (<span>ETT</span>)</strong>. La <span>TDM</span> et l'<span>IRM</span> sont des examens de 2ᵉ intention.</li></ul></div>"},{"i":"112c82e07e91","n":235,"o":"235-10","u":"Etiologies","t":"Connaître les étiologies de la péricardite au cours d’un infarctus du myocarde","q":"Quels sont les points clés concernant les étiologies de la péricardite au cours d’un infarctus du myocarde ?","a":"<div class=\"notion-course\"><ul><li>Au décours d'un <span>infarctus du myocarde</span>, deux types de péricardite sont à connaître, distincts par leur délai et leur mécanisme.</li><li><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë</em></li></ul></div>"},{"i":"a2916b712c1c","n":235,"o":"235-11","u":"Etiologies","t":"Connaître les étiologies de formes cliniques moins fréquentes","q":"Quels sont les points clés concernant les étiologies de formes cliniques moins fréquentes ?","a":"<div class=\"notion-course\"><ul><li>En dehors de la forme <span>virale</span>/idiopathique (<span>90 %</span>), de nombreuses étiologies plus rares sont à connaître — certaines graves.</li><li><em>📎 Items liés : 159 — <span>Tuberculose</span> Enfant / Adulte · 194 — <span>Lupus</span> - SAPL · 264 — <span>Insuffisance rénale chronique</span> · 169 — <span>VIH</span> · 243 — <span><span class=\"nc-orange_bg\"><span class=\"nc-orange_bg\">Hypothyroïdie</span></span></span></em></li></ul></div>"},{"i":"99b904d53f49","n":235,"o":"235-14","u":"Etiologies","t":"Savoir évoquer les principales étiologies devant une tamponnade","q":"Comment évoquer les principales étiologies devant une tamponnade ?","a":"<div class=\"notion-course\"><ul><li>En théorie, <strong>toutes</strong> les péricardites peuvent se compliquer de <span>tamponnade</span>. En pratique, certaines étiologies y exposent beaucoup plus.</li><li><span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">Néoplasiques</span></span></span> <strong>+++</strong> (cause la plus fréquente de <span>tamponnade</span>)</li><li><span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">Hémopéricarde</span></span></span> : <span><span>dissection</span> aortique</span>, post-traumatique, post-<span class=\"nc-pink_bg\"><span class=\"nc-pink_bg\">chirurgicale</span></span>, post-<span>ponction</span></li><li><span>Virale</span> : se complique <strong>exceptionnellement</strong> de <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">tamponnade</span></span></span> (diagnostic d'exclusion)</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181108a00c2b4c904b6c8?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
